{
  "title": "the_tower_rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The scouts gather at the ruined gate.",
      "visual_description": "Dusk light filters through a broken stone archway. Two figures stand in the shadow of a crumbling gate tower, old royal banners fraying above them.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper in the market.",
      "visual_description": "A dusty market square with overturned carts. Huddled civilians glance nervously toward a distant spire, their faces lit by a single oil lamp.",
      "characters": ["townsfolk"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march past the old fountain.",
      "visual_description": "Three helmeted guards in rusted breastplates cross the square, their spears catching the last daylight. A torn banner trails from the fountain’s center.",
      "characters": ["patrol_guard", "patrol_guard", "patrol_guard"]
    },
    {
      "scene_number": 4,
      "caption": "The team hides behind a toppled statue.",
      "visual_description": "Kneeling behind a cracked marble king, the map reader peers around the base while the scout signals silence. Lantern light sweeps near them.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the cursed tower’s base.",
      "visual_description": "A spiraling black stone tower under cold blue moonlight. Strange runes pulse on the iron door. A crystal key dangles from the map reader's hand.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 6,
      "caption": "A magic door hums with silver light.",
      "visual_description": "The door’s surface ripples like water. The scout touches it and their fingers leave glowing ripples. A brass compass hangs from the scout’s belt.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 7,
      "caption": "The sleepy official fumbles with the ledger.",
      "visual_description": "A round, weary clerk in a patched robe sits at a small desk inside the tower entrance, an open ledger before him. He yawns as the scouts enter.",
      "characters": ["sleepy_official", "map_reader", "scout"]
    },
    {
      "scene_number": 8,
      "caption": "The official accidentally reveals the secret.",
      "visual_description": "He knocks over a teacup, revealing a hidden stair diagram on the ledger page. The map reader leans in, pointing at the spiral staircase.",
      "characters": ["sleepy_official", "map_reader", "scout"]
    },
    {
      "scene_number": 9,
      "caption": "The team climbs the cold spiral stair.",
      "visual_description": "Narrow stone steps wind upward, lit by a faint blue glow from cracks in the wall. The map reader holds the crystal key high.",
      "characters": ["map_reader", "scout", "sleepy_official"]
    },
    {
      "scene_number": 10,
      "caption": "A hallucination test from a mirror shard.",
      "visual_description": "A floating shard of mirrored glass shows the scout a vision of a dragon. The scout shakes their head, stepping past it into the real room.",
      "characters": ["map_reader", "scout", "sleepy_official"]
    },
    {
      "scene_number": 11,
      "caption": "The rescue target is found in the top chamber.",
      "visual_description": "A small figure in a tattered cloak sits on a stone floor, manacled to a pillar. Sunlight streams from a high window, illuminating a bridge lever on the wall.",
      "characters": ["map_reader", "scout", "sleepy_official", "rescue_target"]
    },
    {
      "scene_number": 12,
      "caption": "The magic helper wards off a pursuing patrol.",
      "visual_description": "A fourth figure in a flowing robe stands at the chamber door, hands raised as a shimmering barrier forms. Guards slam against it from the other side.",
      "characters": ["magic_helper", "patrol_guard", "patrol_guard"]
    },
    {
      "scene_number": 13,
      "caption": "The crystal key opens the manacles.",
      "visual_description": "Close-up of the key turning in a lock. The manacles fall away. The rescue target rubs their wrists, standing shakily.",
      "characters": ["map_reader", "rescue_target"]
    },
    {
      "scene_number": 14,
      "caption": "The bridge lever is pulled down.",
      "visual_description": "The sleepy official strains to push the heavy lever. Outside the window, a drawbridge begins to lower across a chasm.",
      "characters": ["sleepy_official", "map_reader", "scout", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 15,
      "caption": "The group descends the tower’s outer stair.",
      "visual_description": "Running down a crumbling outer staircase in cold blue light, the rescue target clutching the map reader’s arm. Patrol shouts echo behind them.",
      "characters": ["map_reader", "scout", "sleepy_official", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 16,
      "caption": "Rumored dragon shadow passes overhead.",
      "visual_description": "A vast winged silhouette glides across the moon. The scout looks up, but the creature does not descend. The group hurries on.",
      "characters": ["map_reader", "scout", "sleepy_official", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 17,
      "caption": "The escape bridge groans under their weight.",
      "visual_description": "A long stone bridge with missing parapets stretches across a misty gorge. The group runs across as torches flare behind them. The bridge lever’s mechanism creaks.",
      "characters": ["map_reader", "scout", "sleepy_official", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 18,
      "caption": "Sunrise breaks beyond the far gate.",
      "visual_description": "Golden light spills over the ruined city. The group stands on a grassy hill beyond the bridge, looking back. Old banners flutter in the distance.",
      "characters": ["map_reader", "scout", "sleepy_official", "magic_helper", "rescue_target"]
    }
  ]
}

